// 1. Create Account
const user = new User();
try {
    const result = user.createAccount("user@example.com", "password123");
    console.log(result);  // "Account successfully created!"
} catch (error) {
    console.log(error.message);  // Error handling if email or password is invalid
}

// 2. Request Appointment
try {
    const result = user.requestAppointment("2025-02-18", "10:00");
    console.log(result);  // "Appointment successfully requested."
} catch (error) {
    console.log(error.message);  // Error if slot is unavailable or date/time format is incorrect
}

// 3. Edit Appointment
try {
    const result = user.editAppointment("2025-02-18", "10:00", "2025-02-18", "11:00");
    console.log(result);  // "Appointment successfully updated."
} catch (error) {
    console.log(error.message);  // Error if the appointment doesn't exist or new slot is unavailable
}

// 4. View Appointments
try {
    const appointments = user.viewAppointments();
    console.log(appointments);  // Array of current appointments
} catch (error) {
    console.log(error.message);  // Error if something goes wrong with viewing appointments
}

// 5. Delete Appointment
try {
    const result = user.deleteAppointment("2025-02-18", "10:00");
    console.log(result);  // "Appointment successfully deleted."
} catch (error) {
    console.log(error.message);  // Error if the appointment is not found
}

// 6. Check Available Slots
try {
    const slots = user.checkAvailableSlots("2025-02-18");
    console.log(slots);  // Array of available slots for the date (e.g., ["9:00", "10:00", ...])
